mapper.select:
select csr.*, su.real_name as studentName, suc.real_name as counselorName from cs_consult_record as csr left join sys_user as su on csr.student_id = su.user_id left join sys_user as suc on csr.counselor_id = suc.user_id
and csr.counselor_id = #{counselorId} and csr.student_id = #{studentId} and su.real_name like concat('%', #{studentName}, '%') and csr.archive_status = #{archiveStatus}
order by csr.create_time desc
